class ApplicationTask:
    def __init__(self, cost_C, period_P):
        self.C = cost_C
        self.P = period_P

    def get_deadline(self, invocation_k):
        return (invocation_k + 1) * self.P

class InterruptHandler:
    def __init__(self, cost_E, period_A):
        self.E = cost_E
        self.A = period_A

class TaskSystem:
    def __init__(self, interrupt_handlers, application_tasks):
        self.interrupt_handlers = interrupt_handlers # List of InterruptHandler objects
        self.application_tasks = application_tasks   # List of ApplicationTask objects
        self.num_interrupt_handlers = len(interrupt_handlers)
        self.num_application_tasks = len(application_tasks)

