def calculate_f_L(L, memo={0: 0}):
    if L < 0:
        return 0
    if L in memo:
        return memo[L]

    f_L_minus_1 = calculate_f_L(L - 1, memo)

    current_f_L = 0
    for handler in interrupt_handlers_list:
        current_f_L += ( (f_L_minus_1 + L) // handler.A ) * handler.E

    memo[L] = current_f_L
    return current_f_L

