def check_feasibility_theorem_3_1(application_tasks, max_L_to_check):
    for L in range(0, max_L_to_check + 1): # In practice, L is checked up to LCM or a bound
        demand_L = 0
        for task in application_tasks:
            demand_L += (L // task.P) * task.C

        if L < demand_L:
            return False # Infeasible
    return True # Feasible within the checked range

