f_L_memo = {0: 0}
def calculate_f_L_memoized(L):
    if L < 0: return 0
    if L in f_L_memo: return f_L_memo[L]

    f_L_minus_1 = calculate_f_L_memoized(L - 1)
    current_f_L = 0
    for handler in interrupt_handlers_list:
        current_f_L += ( (f_L_minus_1 + L) // handler.A ) * handler.E

    f_L_memo[L] = current_f_L
    return current_f_L

def check_feasibility_theorem_3_5(task_system, max_L_to_check):
    for L in range(0, max_L_to_check + 1):
        interrupt_demand = calculate_f_L_memoized(L)

        app_task_demand = 0
        for task in task_system.application_tasks:
            app_task_demand += (L // task.P) * task.C

        if (L - interrupt_demand) < app_task_demand:
            return False # Infeasible
    return True # Feasible within the checked range

