def check_necessary_condition_7(task_system):
    if not task_system.application_tasks:
        return True # No application tasks, trivially feasible for this condition

    P_min = float('inf')
    C_min = 0
    for task in task_system.application_tasks:
        if task.P < P_min:
            P_min = task.P
            C_min = task.C

    sum_E = 0
    for handler in task_system.interrupt_handlers:
        sum_E += handler.E

    if (sum_E + C_min) > P_min:
        return False # Infeasible
    return True # Potentially feasible

def analyze_F_L_sufficiency(task_i, L, W_i_L, f_L_val, F_L_val):
    # If the condition with F_L holds:
    if L >= (W_i_L + F_L_val):
        # Since f_L_val <= F_L_val, it implies:
        # L >= (W_i_L + f_L_val)
        return 'Sufficient: System is schedulable.'
    else:
        # If it fails with F_L, it might still pass with f_L
        if L >= (W_i_L + f_L_val):
            return 'Not Necessary: System is schedulable with f_L but not F_L.'
        else:
            return 'Infeasible: Fails with both f_L and F_L.'
